// The differential test's cases, generated by qilin_difftest_gen.
#pragma once

#include <cstdint>

namespace qilin::difftest {

enum Kind : uint8_t {
    plain,    // the instruction, then rts
    slot,     // rts with the instruction in its delay slot
    sz64,     // between two fschg: FPSCR.SZ = 1
    double_,  // between loads of FPSCR setting and clearing PR: double precision
    program,  // a branch program
    loop,     // a dt loop: r1 is its count
    nowhere,  // an indirect branch through r3 to an address with no function
};

struct Case {
    Kind kind;
    uint32_t entry;
    uint32_t insn;  // the instruction under test (0 for the programs)
};

extern const uint16_t kImage[];  // the synthetic boot file, from 0x8C010000
extern const uint32_t kImageWords;
extern const Case kCaseList[];
extern const uint32_t kCaseCount;

}  // namespace qilin::difftest
